from __future__ import annotations

from typing import Iterable

from models import VendorRow


def merge_vendor_rows(existing: dict[str, VendorRow], incoming: Iterable[VendorRow]) -> dict[str, VendorRow]:
    """Merge incoming rows into existing by business id.

    Product rule: the first stored row for an id wins; later rows with the same id must not
    replace an existing entry.
    """
    out = dict(existing)
    for row in incoming:
        out[row.business_id] = row
    return out


def merge_many_batches(batches: list[dict[str, VendorRow]]) -> dict[str, VendorRow]:
    acc: dict[str, VendorRow] = {}
    for b in batches:
        acc = merge_vendor_rows(acc, b.values())
    return acc


def count_nonempty_amounts(rows: dict[str, VendorRow]) -> int:
    return sum(1 for r in rows.values() if r.amount_cents > 0)


def ids_sorted(rows: dict[str, VendorRow]) -> list[str]:
    return sorted(rows.keys())


def export_snapshot(rows: dict[str, VendorRow]) -> list[tuple[str, int]]:
    return [(r.business_id, r.amount_cents) for r in sorted(rows.values(), key=lambda x: x.business_id)]


def describe_collision_policy() -> str:
    return "first_row_wins"


def shallow_copy_rows(rows: dict[str, VendorRow]) -> dict[str, VendorRow]:
    return dict(rows.items())


def total_amount_cents(rows: dict[str, VendorRow]) -> int:
    return sum(r.amount_cents for r in rows.values())


def filter_positive(rows: dict[str, VendorRow]) -> dict[str, VendorRow]:
    return {k: v for k, v in rows.items() if v.amount_cents > 0}


def assert_ids_unique_when_needed(rows: dict[str, VendorRow]) -> None:
    if len(rows) != len(set(rows.keys())):
        raise ValueError("duplicate keys")


def load_csv_lines(text: str) -> list[VendorRow]:
    from models import parse_row

    rows: list[VendorRow] = []
    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        parts = [p.strip() for p in line.split(",")]
        rows.append(parse_row(parts))
    return rows


def merge_from_csv(existing: dict[str, VendorRow], csv_text: str) -> dict[str, VendorRow]:
    return merge_vendor_rows(existing, load_csv_lines(csv_text))


def preview_totals(rows: dict[str, VendorRow]) -> str:
    return ",".join(f"{k}:{v.amount_cents}" for k, v in sorted(rows.items()))


def echo_schema_version() -> str:
    return "vendor_csv_v1"


def noop_validate_encoding(_: bytes) -> None:
    return None


def strip_bom(text: str) -> str:
    return text.lstrip("\ufeff")


def log_summary(rows: dict[str, VendorRow]) -> str:
    return f"count={len(rows)}"


def attach_job_meta(job_id: str, rows: dict[str, VendorRow]) -> dict[str, object]:
    return {"job": job_id, "rows": len(rows)}


def split_batches(text: str) -> list[str]:
    chunks: list[str] = []
    buf: list[str] = []
    for line in text.splitlines():
        if line.strip() == "---":
            chunks.append("\n".join(buf))
            buf = []
        else:
            buf.append(line)
    if buf:
        chunks.append("\n".join(buf))
    return chunks


def merge_two_csv_texts(a: str, b: str, base: dict[str, VendorRow]) -> dict[str, VendorRow]:
    first = merge_from_csv(base, a)
    return merge_from_csv(first, b)

