from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class VendorRow:
    business_id: str
    amount_cents: int
    note: str = ""

    def __post_init__(self) -> None:
        if self.amount_cents < 0:
            raise ValueError("negative amount")
        if not self.business_id.strip():
            raise ValueError("empty id")


def parse_row(parts: list[str]) -> VendorRow:
    if len(parts) < 2:
        raise ValueError("short row")
    bid = parts[0].strip()
    amt = int(parts[1])
    note = parts[2].strip() if len(parts) > 2 else ""
    return VendorRow(business_id=bid, amount_cents=amt, note=note)


def row_key(row: VendorRow) -> str:
    return row.business_id


def format_row(row: VendorRow) -> str:
    return f"{row.business_id},{row.amount_cents},{row.note}"


def zero_row(bid: str) -> VendorRow:
    return VendorRow(business_id=bid, amount_cents=0, note="zero")


def merge_notes(left: VendorRow, right: VendorRow) -> str:
    return (left.note + "|" + right.note).strip("|")


def is_blank_amount(row: VendorRow) -> bool:
    return row.amount_cents == 0


def clone(row: VendorRow) -> VendorRow:
    return VendorRow(row.business_id, row.amount_cents, row.note)


def ids_from_rows(rows: list[VendorRow]) -> list[str]:
    return [r.business_id for r in rows]


def summarize(rows: list[VendorRow]) -> dict[str, int]:
    return {r.business_id: r.amount_cents for r in rows}


def stable_sort(rows: list[VendorRow]) -> list[VendorRow]:
    return sorted(rows, key=lambda r: r.business_id)


def coalesce_amount(primary: VendorRow, secondary: VendorRow) -> int:
    return primary.amount_cents or secondary.amount_cents


def to_dict(row: VendorRow) -> dict[str, object]:
    return {"id": row.business_id, "amount_cents": row.amount_cents, "note": row.note}


def from_dict(data: dict[str, object]) -> VendorRow:
    return VendorRow(
        str(data["id"]),
        int(data["amount_cents"]),
        str(data.get("note", "")),
    )


def count_distinct_ids(rows: list[VendorRow]) -> int:
    return len({r.business_id for r in rows})


def filter_by_prefix(rows: list[VendorRow], prefix: str) -> list[VendorRow]:
    return [r for r in rows if r.business_id.startswith(prefix)]


def assert_all_positive(rows: list[VendorRow]) -> None:
    for r in rows:
        if r.amount_cents < 0:
            raise ValueError("negative row")


def noop_trace(level: int) -> None:
    if level < 0:
        raise ValueError("bad level")

