import pytest

from merge import merge_from_csv, merge_two_csv_texts, merge_vendor_rows
from models import VendorRow


def test_happy_path_first_row_keeps_amount_when_second_duplicate_arrives():
    base = {"A1": VendorRow("A1", 100, "first")}
    incoming = [VendorRow("A1", 999, "second")]
    out = merge_vendor_rows(base, incoming)
    assert out["A1"].amount_cents == 100


def test_edge_case_new_id_still_appends():
    base: dict[str, VendorRow] = {}
    incoming = [VendorRow("Z9", 50, "")]
    out = merge_vendor_rows(base, incoming)
    assert out["Z9"].amount_cents == 50


def test_boundary_condition_empty_existing_dict():
    out = merge_vendor_rows({}, [VendorRow("B1", 1, "")])
    assert list(out.keys()) == ["B1"]


def test_unexpected_input_negative_amount_rejected():
    with pytest.raises(ValueError):
        VendorRow("X", -1, "")


def test_integration_two_csv_texts_duplicate_preserves_first_amount():
    base: dict[str, VendorRow] = {}
    out = merge_two_csv_texts("C1,10,alpha", "C1,40,beta", base)
    assert out["C1"].amount_cents == 10
